import triton
import triton.language as tl

# pi / 180 as full double-precision literal
_C = 0.017453292519943295


@triton.jit
def _deg2rad_kernel(in_ptr, out_ptr, numel, C, BLOCK_SIZE: tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offs < numel
    x = tl.load(in_ptr + offs, mask=mask)
    tl.store(out_ptr + offs, x * C, mask=mask)


@triton.jit
def _deg2rad_head_kernel(head_ptr, out_ptr, count, C, BLOCK_SIZE: tl.constexpr):
    offs = tl.arange(0, BLOCK_SIZE)
    mask = offs < count
    x = tl.load(head_ptr + offs, mask=mask)
    tl.store(out_ptr + offs, x * C, mask=mask)


def deg2rad_(x):
    numel = x.numel()
    if numel == 0:
        return x
    BLOCK_SIZE = 4096
    v = x.contiguous().view(-1)  # aliases x's storage when already contiguous

    # This flagtree/Ascend Triton backend miscompiles ONLY the first program
    # block (pid=0) of a true in-place kernel whose load and store share the
    # same pointer, zeroing those elements. Verified (8 repeats x many shapes x
    # fp16/bf16/fp32) that the defect is confined to block 0. So: save the head
    # block, run the correct-for-blocks>=1 in-place pass over all elements, then
    # recompute just the head block from the saved copy. This keeps a single
    # full read+write pass over x (half the HBM traffic of an out-of-place
    # kernel plus a separate copy), and the compute stays in the Triton kernels.
    num_blocks = triton.cdiv(numel, BLOCK_SIZE)
    if num_blocks == 1:
        # Only the (miscompiled) head block would exist. Skip the in-place pass
        # entirely and compute the single block out-of-place from a saved copy
        # directly back into x: one kernel launch, correct on this backend.
        head = v.clone()
        _deg2rad_head_kernel[(1,)](head, v, numel, _C, BLOCK_SIZE=BLOCK_SIZE)
        return x

    head_count = BLOCK_SIZE
    head = v[:head_count].clone()
    _deg2rad_kernel[(num_blocks,)](v, v, numel, _C, BLOCK_SIZE=BLOCK_SIZE)
    _deg2rad_head_kernel[(1,)](head, v, head_count, _C, BLOCK_SIZE=BLOCK_SIZE)
    return x
